 check(finite(e['frictionCoefficient'],0,2) and finite(e['durationSeconds'],.1,2) and finite(e['stepSeconds'],.0001,.01) and e['durationSeconds']/e['stepSeconds']<=2000,'Bounded numerical experiment required')
