 pins={str(p.relative_to(ROOT)):sha(p) for p in files};receipt={'schema':'frc-fuel-plane-execution/v1','status':'running','sourcePins':pins,'engineeringAcceptance':'blocked','actualRobotIoExecuted':False,'fieldMeshUsed':False,'capture':None,'score':None,'calibration':'none','normalLaw':'assumed-rigid-perfectly-inelastic','requiredDomains':{'physics':'partial-unvalidated-sphere-plane','voltage':'not-run-component-foundation','heat':'unsupported','friction':'assumed-unvalidated','weightDistribution':'unsupported-robot'},'python':sys.version,'javaExecutableSha256':sha(pathlib.Path(a.java_home)/'bin/java.exe'),'invocation':['gradlew.bat','fuelPlaneTest','dependencyManifest','--offline','--rerun-tasks']}
 def save():(out/'execution-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
