  e=json.loads((ROOT/'references/fuel-plane-experiment.json').read_text());c=json.loads((ROOT/'case-studies/2026/roller-mechanism.json').read_text());case=json.loads((ROOT/'case-studies/2026/case.json').read_text());validate(e,c,case);mh=sha(manual);check(mh==e['pieceSource']['sha256'],'Exact reviewed manual bytes required');receipt['manualSha256']=mh;receipt['manualBytes']=manual.stat().st_size;receipt['manualUse']='Hash correspondence to independently reviewed source, not automatic PDF interpretation'
